import React, { useState } from "react";
import { useNavigate } from "react-router-dom";

const Uploads = () => {
  const navigate = useNavigate();
  const [patientName, setPatientName] = useState("");
  const [patientId, setPatientId] = useState("");
  const [gender, setGender] = useState("Male");
  const [age, setAge] = useState("");
  const [date, setDate] = useState("");
  const [images, setImages] = useState([]);

  const handleImageChange = (e) => {
    const files = Array.from(e.target.files);
    if (files.length > 0) {
      const newImages = files.map((file) => ({
        id: Math.random().toString(36).substr(2, 9),
        url: URL.createObjectURL(file),
        file,
      }));
      setImages((prev) => [...prev, ...newImages]);
    }
  };

  const handleRemoveImage = (id) => {
    setImages((prev) => prev.filter((img) => img.id !== id));
  };

  const handleScan = (e) => {
    e.preventDefault();
    if (images.length === 0) {
      alert("Please upload at least one image before scanning!");
      return;
    }
    navigate("/Analysis", {
      state: { patientName, patientId, gender, age, date, images },
    });
  };

  return (
    <div className="font-sans flex flex-col items-center bg-[#0B0F1A] text-[#E0E6F0] min-h-screen p-5">
        {/* Image Upload Section */}
      <div className="mb-8 flex flex-col items-center w-full max-w-2xl">
        <div className="text-center mb-4">
          <h2 className="text-xl font-bold text-[#E0E6F0] bg-[#152033] p-3 rounded-t-md">
            Upload X-ray Images
          </h2>
          <p className="text-[#AAB6C5] bg-[#152033] p-2 rounded-b-md font-medium">
            Upload single or multiple images to perform scanning
          </p>
        </div>

        {/* Upload area */}
        <div className="w-full border-2 border-dashed border-[#00B0FF] rounded-md bg-[#111827] flex flex-col items-center justify-center p-6 hover:bg-[#1B263B] transition-colors cursor-pointer">
          <label className="flex flex-col items-center justify-center w-full cursor-pointer">
            <input
              type="file"
              accept="image/*"
              onChange={handleImageChange}
              className="hidden"
              multiple
            />
            <p className="text-[#00B0FF] font-medium">
              Drag and drop or{" "}
              <span className="underline cursor-pointer">Choose images</span>
            </p>
          </label>
        </div>

        {/* Image Preview Grid */}
        {images.length > 0 && (
          <div className="mt-6 grid grid-cols-2 sm:grid-cols-3 gap-4 w-full">
            {images.map((img) => (
              <div
                key={img.id}
                className="relative group rounded-md overflow-hidden border border-[#1E2A40]"
              >
                <img
                  src={img.url}
                  alt="Preview"
                  className="object-cover w-full h-40 rounded-md"
                />
                {/* Remove Button */}
                <button
                  type="button"
                  onClick={() => handleRemoveImage(img.id)}
                  className="absolute top-2 right-2 bg-red-600 hover:bg-red-700 text-white text-xs px-2 py-1 rounded opacity-90 group-hover:opacity-100 transition"
                >
                  Remove
                </button>
              </div>
            ))}
          </div>
        )}
      </div>

      {/* Patient Information Section */}
      <div className="w-full max-w-md text-center mb-4">
        <h2 className="text-xl font-semibold text-white mb-2">
          Fill in Patient Information form
        </h2>
      </div>

      {/* Patient Info Form */}
      <form
        onSubmit={handleScan}
        className="max-w-md w-full flex flex-col gap-4 bg-[#152033] p-6 rounded-md shadow-lg border border-[#1E2A40]"
      >
        <input
          type="text"
          placeholder="Patient Name"
          value={patientName}
          onChange={(e) => setPatientName(e.target.value)}
          className="p-3 rounded-md bg-[#0F172A] border border-[#1E2A40] text-[#E0E6F0] placeholder-[#9CA3AF] focus:outline-none focus:ring-2 focus:ring-[#00B0FF]"
          required
        />
        <input
          type="text"
          placeholder="Patient ID"
          value={patientId}
          onChange={(e) => setPatientId(e.target.value)}
          className="p-3 rounded-md bg-[#0F172A] border border-[#1E2A40] text-[#E0E6F0] placeholder-[#9CA3AF] focus:outline-none focus:ring-2 focus:ring-[#00B0FF]"
          required
        />
        <select
          value={gender}
          onChange={(e) => setGender(e.target.value)}
          className="p-3 rounded-md bg-[#0F172A] border border-[#1E2A40] text-[#E0E6F0] focus:outline-none focus:ring-2 focus:ring-[#00B0FF]"
        >
          <option value="Male" className="bg-[#0B0F1A]">
            Male
          </option>
          <option value="Female" className="bg-[#0B0F1A]">
            Female
          </option>
        </select>
        <input
          type="number"
          placeholder="Age"
          value={age}
          onChange={(e) => setAge(e.target.value)}
          className="p-3 rounded-md bg-[#0F172A] border border-[#1E2A40] text-[#E0E6F0] placeholder-[#9CA3AF] focus:outline-none focus:ring-2 focus:ring-[#00B0FF]"
          required
        />
        <input
          type="date"
          value={date}
          onChange={(e) => setDate(e.target.value)}
          className="p-3 rounded-md bg-[#0F172A] border border-[#1E2A40] text-[#E0E6F0] focus:outline-none focus:ring-2 focus:ring-[#00B0FF]"
          required
        />

        <button
          type="submit"
          className="bg-green-600 text-white font-semibold p-3 rounded-md hover: transition-colors"
        >
          Scan
        </button>
      </form>
    </div>
  );
};

export default Uploads;
